class Solution {
public:
    long long minimalKSum(vector<int>& nums, int k) {
        long long ans = (long long)k * (k + 1) / 2;
        sort(nums.begin(), nums.end());
        int last = 0;
        for (int x : nums) {
            if (x == last) continue;
            last = x;
            if (x <= k) {
                ans += (long long)(k + 1) - x;
                k++;
            }
        }
        return ans;
    }
};

class Solution {
    public long minimalKSum(int[] nums, int k) {
        long ans = (long) k * (k + 1) / 2;
        Arrays.sort(nums);
        int last = 0;
        for (int x : nums) {
            if (x == last) continue;
            last = x;
            if (x <= k) {
                ans += (long) (k + 1) - x;
                k++;
            }
        }
        return ans;
    }
}

