var minimalKSum = function(nums, k) {
    let ans = BigInt(k) * BigInt(k + 1) / 2n;
    const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
    for (const x of sorted) {
        if (x <= k) {
            ans += BigInt(k + 1) - BigInt(x);
            k++;
        }
    }
    return Number(ans);
};
